#!/usr/bin/env python3
import json, re
from pathlib import Path
from html import escape
ROOT=Path(__file__).resolve().parents[1]
DATE='2026-09-08'; BASE='https://epochlex.justathoughtblog.org'
BATCH=[
{'term':'AI Literacy','slug':'ai-literacy','pronunciation':'A-I LIT-er-uh-see','definition':'The knowledge and skills needed to understand, use, evaluate, and make informed decisions about artificial intelligence, including awareness of its capabilities, limitations, and risks.','example':'The training focused on AI literacy so employees could use AI tools appropriately and recognize when their outputs needed closer review.','categories':['AI Ways of Working','AI Risks, Safety & Governance'],'aliases':['Artificial intelligence literacy'],'status':'Established governance and education term','partOfSpeech':'noun','related':['artificial-intelligence','ai-governance','responsible-ai','human-in-the-loop'],'sources':[{'id':'ec-ai-literacy-2026','type':'primary','publisher':'European Commission','title':'AI talent, skills and literacy','published':'2026','url':'https://digital-strategy.ec.europa.eu/en/policies/ai-talent-skills-and-literacy','supports':['definition','usage']}]},
{'term':'Indirect Prompt Injection','slug':'indirect-prompt-injection','pronunciation':'in-duh-REKT prompt in-JEK-shun','definition':'A prompt-injection attack in which malicious or conflicting instructions reach an AI system through external content such as a webpage, document, message, or retrieved data rather than directly from the user.','example':'The agent encountered an indirect prompt injection hidden inside a webpage it had been asked to summarize.','categories':['AI Risks, Safety & Governance'],'aliases':['Indirect prompt injection attack'],'status':'Technical security term','partOfSpeech':'noun','related':['prompt-injection','jailbreak','tool-calling','rag'],'sources':[{'id':'owasp-indirect-prompt-injection-2025','type':'reference','publisher':'OWASP GenAI Security Project','title':'LLM01:2025 Prompt Injection','published':'2025','url':'https://genai.owasp.org/llmrisk/llm01-prompt-injection/','supports':['definition','usage','risk']}]},
{'term':'Data Poisoning','slug':'data-poisoning','pronunciation':'DAY-tuh POY-zuh-ning','definition':'An attack in which an adversary manipulates or inserts data used for training or adaptation so the resulting AI model learns unwanted behavior, loses performance, or develops a hidden vulnerability.','example':'The security review considered whether data poisoning could alter the model by contaminating part of its training dataset.','categories':['AI Risks, Safety & Governance','AI Systems & Technical Concepts'],'aliases':['Training data poisoning'],'status':'Established security term','partOfSpeech':'noun','related':['training-data','adversarial-attack','model-collapse','fine-tuning'],'sources':[{'id':'nist-data-poisoning-2025','type':'primary','publisher':'NIST','title':'Adversarial Machine Learning: A Taxonomy and Terminology of Attacks and Mitigations','published':'2025-03-24','url':'https://csrc.nist.gov/glossary/term/data_poisoning','supports':['definition','usage','risk']}]},
{'term':'Model Card','slug':'model-card','pronunciation':'MOD-ul kard','definition':'A structured document that accompanies an AI or machine-learning model and describes information such as its intended uses, evaluation results, performance characteristics, limitations, and relevant context for responsible use.','example':'The team reviewed the model card before deciding whether the model was appropriate for the intended deployment.','categories':['AI Risks, Safety & Governance','AI Systems & Technical Concepts'],'aliases':['Model cards'],'status':'Established documentation term','partOfSpeech':'noun','related':['system-card','model-evaluation','benchmark','responsible-ai'],'sources':[{'id':'google-model-cards-2019','type':'primary','publisher':'Google Research','title':'Model Cards for Model Reporting','published':'2019','url':'https://research.google/pubs/model-cards-for-model-reporting/','supports':['definition','usage']}]},
{'term':'System Card','slug':'system-card','pronunciation':'SIS-tum kard','definition':'A document published about an AI system or major model release that summarizes evaluations, identified risks, safety measures, limitations, and other information relevant to understanding how the system was assessed and deployed.','example':'The release included a system card describing safety evaluations, observed risks, and the safeguards used before deployment.','categories':['AI Risks, Safety & Governance','AI Systems & Technical Concepts'],'aliases':['System cards'],'status':'Established AI safety documentation term','partOfSpeech':'noun','related':['model-card','red-teaming','ai-governance','benchmark'],'sources':[{'id':'openai-gpt55-system-card-2026','type':'primary','publisher':'OpenAI','title':'GPT-5.5 System Card','published':'2026-04-23','url':'https://openai.com/index/gpt-5-5-system-card/','supports':['definition','usage']}]},
{'term':'Agentic Workflow','slug':'agentic-workflow','pronunciation':'ay-JEN-tik WURK-floh','definition':'A multi-step AI workflow that uses agentic behavior such as model-directed decisions, tool use, routing, iteration, or delegation to move a task toward a goal.','example':'The research process used an agentic workflow that searched for sources, evaluated them, and decided when another retrieval step was needed.','categories':['AI Ways of Working','AI Systems & Technical Concepts'],'aliases':['Agentic workflows'],'status':'Established emerging term','partOfSpeech':'noun','related':['agentic','ai-agent','orchestration','prompt-chaining'],'sources':[{'id':'anthropic-building-agents','type':'primary','publisher':'Anthropic','title':'Building Effective AI Agents','published':'2024-12-19','url':'https://www.anthropic.com/engineering/building-effective-agents','supports':['definition','usage']}]},
{'term':'Agent Loop','slug':'agent-loop','pronunciation':'AY-jent loop','definition':'A recurring cycle in which an AI agent observes its current state or results, decides what to do next, takes an action or uses a tool, evaluates the outcome, and repeats until it reaches a stopping condition.','example':'The agent loop continued after the first search because the retrieved evidence was not yet sufficient to answer the question.','categories':['AI Ways of Working','AI Systems & Technical Concepts'],'aliases':['Agentic loop'],'status':'Established emerging technical term','partOfSpeech':'noun','related':['ai-agent','agentic','tool-calling','orchestration'],'sources':[{'id':'anthropic-building-agents-loop','type':'primary','publisher':'Anthropic','title':'Building Effective AI Agents','published':'2024-12-19','url':'https://www.anthropic.com/engineering/building-effective-agents','supports':['definition','usage']}]},
{'term':'AI Companion','slug':'ai-companion','pronunciation':'A-I kum-PAN-yun','definition':'An AI system, often conversational, designed or used for ongoing social interaction, companionship, emotional support, or a simulated interpersonal relationship.','example':'The study examined how people used an AI companion for conversation and emotional support over time.','categories':['AI Culture & Slang','AI Risks, Safety & Governance'],'aliases':['Artificial intelligence companion'],'status':'Established emerging term','partOfSpeech':'noun','related':['artificial-intelligence','chatgpt','synthetic-content'],'sources':[{'id':'stanford-ai-companions-2026','type':'secondary','publisher':'Stanford University','title':'AI companions may worsen loneliness for vulnerable users','published':'2026-08-04','url':'https://news.stanford.edu/stories/2026/08/ai-companions-chatbots-loneliness-research','supports':['definition','usage','risk']}]},
{'term':'Human-AI Collaboration','slug':'human-ai-collaboration','pronunciation':'HYOO-muhn A-I kuh-lab-uh-RAY-shun','definition':'A way of working in which people and AI systems contribute to a shared task or goal, with each providing capabilities, information, judgment, or actions that shape the combined result.','example':'The design review used human-AI collaboration: the AI organized alternatives while the team evaluated tradeoffs and made the final decisions.','categories':['AI Ways of Working'],'aliases':['Human-AI teaming'],'status':'Established','partOfSpeech':'noun','related':['human-in-the-loop','copilot','ai-agent','ai-native'],'sources':[{'id':'nist-human-ai-collaboration-2025','type':'reference','publisher':'NIST','title':'Economic Research and Analysis of the National Need for Technology Infrastructure to Support the Internet of Things (IoT)','published':'2025','url':'https://nvlpubs.nist.gov/nistpubs/gcr/2025/NIST.GCR.25-059.pdf','supports':['definition','usage']}]},
{'term':'Sampling','slug':'sampling','pronunciation':'SAM-pling','definition':'A generation method in which an AI model selects among possible next tokens according to a probability distribution rather than always choosing only the single highest-probability option.','example':'Using sampling instead of greedy decoding produced more varied responses from the language model.','categories':['AI Systems & Technical Concepts'],'aliases':['Token sampling','Probabilistic sampling'],'status':'Technical','partOfSpeech':'noun','related':['temperature','top-p','token','large-language-model'],'sources':[{'id':'huggingface-generation-sampling','type':'reference','publisher':'Hugging Face','title':'How to generate text: using different decoding methods for language generation with Transformers','published':'2020','url':'https://huggingface.co/blog/how-to-generate','supports':['definition','usage']}]}
]

def page(t):
    term=escape(t['term']); d=escape(t['definition'],quote=True); p=escape(t['pronunciation']); slug=t['slug']; url=f'{BASE}/terms/{slug}/'
    return f'''<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="color-scheme" content="light dark">\n  <title>{term} | EpochLex</title>\n  <meta name="description" content="{d}">\n  <link rel="canonical" href="{url}">\n  <meta property="og:site_name" content="EpochLex">\n  <meta property="og:title" content="{term} | EpochLex">\n  <meta property="og:description" content="{d}">\n  <meta property="og:type" content="article">\n  <meta property="og:url" content="{url}">\n  <meta name="twitter:card" content="summary">\n  <meta name="twitter:title" content="{term} | EpochLex">\n  <meta name="twitter:description" content="{d}">\n  <script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'DefinedTerm','name':t['term'],'description':t['definition'],'url':url,'inDefinedTermSet':BASE+'/','inLanguage':'en'},ensure_ascii=False)}</script>\n  <script>(()=>{{try{{const saved=localStorage.getItem("ai-era-theme");const systemDark=window.matchMedia("(prefers-color-scheme: dark)").matches;document.documentElement.dataset.theme=saved||(systemDark?"dark":"light");}}catch(_){{document.documentElement.dataset.theme="light";}}}})();</script>\n  <link rel="stylesheet" href="../../assets/css/styles.css">\n  <link rel="stylesheet" href="../../assets/css/term-pages.css">\n  <link rel="stylesheet" href="../../assets/css/brand-theme.css">\n</head>\n<body>\n<header class="site-header"><div class="shell header-inner"><a class="brand" href="../../" aria-label="EpochLex home"><span class="brand-lockup" aria-hidden="true"><img class="brand-lockup-image brand-lockup-light" src="../../assets/brand/epochlex/epochlex-logo-horizontal-light.png" alt=""><img class="brand-lockup-image brand-lockup-dark" src="../../assets/brand/epochlex/epochlex-logo-horizontal-dark.png" alt=""></span><span class="sr-only">EpochLex</span></a><nav class="primary-nav" aria-label="Primary navigation"><a class="active" href="../../">Browse</a><a href="../../categories.html">Categories</a><a href="../../about.html">About</a><a href="../../contribute.html">Contribute</a><a href="../../methodology.html">Methodology</a></nav><button id="theme-toggle" class="theme-toggle" type="button" aria-label="Switch color theme" title="Switch color theme"><span class="sun" aria-hidden="true">☼</span><span class="toggle-track"><span class="toggle-knob"></span></span><span class="moon" aria-hidden="true">☾</span></button></div></header>\n<main id="term-page" class="term-page shell" data-term-slug="{slug}"><div id="term-fallback" class="term-fallback"><nav class="term-breadcrumb" aria-label="Breadcrumb"><a href="../../">Browse</a><span aria-hidden="true">/</span><span>{term}</span></nav><p class="eyebrow">EpochLex entry</p><h1>{term}</h1><p class="fallback-pronunciation">{p}</p><p class="fallback-definition">{escape(t['definition'])}</p></div></main>\n<footer class="site-footer"><div class="shell footer-inner"><span class="footer-mark" aria-hidden="true">◎</span><p><strong>EpochLex · Dictionary of the AI Era</strong><br>Vibe coded · Human-directed · AI-assisted · Human-reviewed</p><p class="footer-license">Code: MIT · Content: CC BY 4.0</p></div></footer><script src="../../assets/js/app.js"></script><script src="../../assets/js/term-page.js"></script>\n</body>\n</html>\n'''

terms_path=ROOT/'data/terms.json'; terms=json.loads(terms_path.read_text())
existing={t['slug'] for t in terms}
for b in BATCH:
    if b['slug'] in existing: raise SystemExit(f"already published: {b['slug']}")
    rec={k:v for k,v in b.items() if k not in ('related','sources')}; rec.update({'added':DATE,'lastReviewed':DATE,'sources':[]}); terms.append(rec)
terms.sort(key=lambda x:x['term'].lower())
terms_path.write_text(json.dumps(terms,ensure_ascii=False,separators=(',',':'))+'\n')

prov_path=ROOT/'data/provenance.json'; prov=json.loads(prov_path.read_text())
for b in BATCH:
    prov[b['slug']]={'researchStatus':'pending','origin':None,'firstKnownUse':None,'history':[],'relatedTerms':b['related'],'sources':b['sources']}
prov_path.write_text(json.dumps(prov,ensure_ascii=False,indent=2)+'\n')

for b in BATCH:
    p=ROOT/'terms'/b['slug']; p.mkdir(parents=True,exist_ok=True); (p/'index.html').write_text(page(b))

# Remove published candidates and update count.
cand_path=ROOT/'docs/CORPUS-CANDIDATES.md'; text=cand_path.read_text()
for b in BATCH:
    text=re.sub(r'^- (?:\[[^\]]+\]\([^\n]+\)|'+re.escape(b['term'])+r')\s*$', lambda m: '' if (b['term'] in m.group(0)) else m.group(0), text, flags=re.M)
text=re.sub(r'\n{3,}','\n\n',text)
# Count bullet candidates between inventory and related docs; audit prose isn't in this file.
start=text.index('## Repository roadmap candidates'); end=text.index('## Related documentation'); count=sum(1 for line in text[start:end].splitlines() if line.startswith('- '))
text=re.sub(r'\*\*Current unpublished inventory: \d+ candidates\.\*\*',f'**Current unpublished inventory: {count} candidates.**',text,count=1)
cand_path.write_text(text)

# Extend audit with Batch B details and remove these terms from next-qualified list.
audit=ROOT/'docs/CORPUS-AUDIT-2026-09.md'; a=audit.read_text()
insert='''\n## Publish — Batch B (published September 8, 2026)\n\n'''
for b in BATCH:
    src='; '.join(f"[{s['publisher']}: {s['title']}]({s['url']})" for s in b['sources'])
    insert+=f"### {b['term']}\n\n**Why publish:** {b['definition']}\n\n**Usage evidence:** {src}\n\n**Provenance state:** `pending` — meaning/usage evidence is recorded; origin, first-known-use, and fuller history research remain open.\n\n"
anchor='## Publish — next qualified group'
a=a.replace(anchor,insert+anchor)
for b in BATCH:
    a=re.sub(r'^- '+re.escape(b['term'])+r'\s*$','',a,flags=re.M)
a=a.replace('This audit publishes 8 candidates immediately and adds 172 new research candidates.','This audit has now published 18 candidates across Batches A and B and added 172 new research candidates.')
audit.write_text(re.sub(r'\n{3,}','\n\n',a))

# Roadmap counts.
road=ROOT/'docs/ROADMAP.md'; r=road.read_text(); r=r.replace('- 130 published dictionary entries;','- 140 published dictionary entries;').replace('- 122 researched provenance records and 8 pending provenance records in the current published corpus;','- 122 researched provenance records and 18 pending provenance records in the current published corpus;'); road.write_text(r)

# Sitemap entries before closing urlset.
site=ROOT/'sitemap.xml'; s=site.read_text(); blocks=''.join(f'  <url>\n    <loc>{BASE}/terms/{b["slug"]}/</loc>\n    <lastmod>{DATE}</lastmod>\n  </url>\n' for b in BATCH); s=s.replace('</urlset>',blocks+'</urlset>'); site.write_text(s)

# Validate.
terms2=json.loads(terms_path.read_text()); prov2=json.loads(prov_path.read_text()); slugs={x['slug'] for x in terms2}
assert len(terms2)==140, len(terms2); assert slugs==set(prov2); assert sum(1 for x in prov2.values() if x.get('researchStatus')=='pending')==18
assert count==733, count
for b in BATCH: assert (ROOT/'terms'/b['slug']/'index.html').exists()
print('Validated Batch B: 140 published, 18 pending provenance, 733 unpublished candidates.')